import os, uuid, time, logging, datetime as dt
import jwt, bcrypt, redis
from flask import Flask, request, jsonify

BASE = '/app'
KEYS = os.path.join(BASE, 'keys')
LOG_DIR = os.path.join(BASE, 'logs')
os.makedirs(LOG_DIR, exist_ok=True)
logging.basicConfig(filename=os.path.join(LOG_DIR, 'app.log'), level=logging.INFO, format='%(asctime)s %(levelname)s %(name)s %(message)s')
log = logging.getLogger('api')

ISSUER = 'rsa-jwt-api'
ACCESS_TTL = dt.timedelta(minutes=15)
REFRESH_TTL = dt.timedelta(days=7)

with open(os.path.join(KEYS, 'private.pem'), 'rb') as f:
    PRIVATE_KEY = f.read()
with open(os.path.join(KEYS, 'public.pem'), 'rb') as f:
    PUBLIC_KEY = f.read()

USERS = {'admin': bcrypt.hashpw(b'password123', bcrypt.gensalt())}

redis_client = redis.Redis(host=os.environ.get('REDIS_HOST', 'localhost'), port=int(os.environ.get('REDIS_PORT', '6379')), db=0, decode_responses=True, socket_timeout=3)

app = Flask(__name__)

def make_token(sub, ttl, ttype):
    now = dt.datetime.now(dt.timezone.utc)
    payload = {'iss': ISSUER, 'sub': sub, 'iat': now, 'exp': now + ttl, 'jti': str(uuid.uuid4()), 'type': ttype}
    return jwt.encode(payload, PRIVATE_KEY, algorithm='RS256')

def err(code, msg):
    log.warning('HTTP %s: %s', code, msg)
    return jsonify({'error': msg}), code

def check_token(token, expected_type=None):
    if not token:
        return None, (401, 'token missing')
    try:
        payload = jwt.decode(token, PUBLIC_KEY, algorithms=['RS256'], issuer=ISSUER, options={'require': ['exp', 'iat', 'jti', 'sub', 'iss']})
    except jwt.ExpiredSignatureError:
        return None, (401, 'token expired')
    except jwt.InvalidTokenError as e:
        return None, (401, 'invalid token: %s' % e)
    if expected_type and payload.get('type') != expected_type:
        return None, (401, 'wrong token type')
    try:
        revoked = redis_client.exists('blacklist:%s' % payload['jti'])
    except redis.RedisError as e:
        log.error('redis unavailable during blacklist check: %s', e)
        return None, (503, 'blacklist unavailable')
    if revoked:
        return None, (403, 'token revoked')
    return payload, None

@app.route('/auth/public-key', methods=['GET'])
def public_key():
    return PUBLIC_KEY, 200, {'Content-Type': 'application/x-pem-file'}

@app.route('/auth/login', methods=['POST'])
def login():
    data = request.get_json(silent=True) or {}
    username = data.get('username', '')
    password = data.get('password', '')
    hashed = USERS.get(username)
    if not hashed or not bcrypt.checkpw(password.encode(), hashed):
        return err(401, 'invalid credentials')
    access = make_token(username, ACCESS_TTL, 'access')
    refresh = make_token(username, REFRESH_TTL, 'refresh')
    log.info('login success for %s', username)
    return jsonify({'access_token': access, 'refresh_token': refresh, 'token_type': 'Bearer', 'expires_in': int(ACCESS_TTL.total_seconds())}), 200

@app.route('/auth/refresh', methods=['POST'])
def refresh():
    data = request.get_json(silent=True) or {}
    payload, error = check_token(data.get('refresh_token'), 'refresh')
    if error:
        return err(*error)
    access = make_token(payload['sub'], ACCESS_TTL, 'access')
    log.info('access token refreshed for %s', payload['sub'])
    return jsonify({'access_token': access, 'token_type': 'Bearer', 'expires_in': int(ACCESS_TTL.total_seconds())}), 200

@app.route('/auth/revoke', methods=['POST'])
def revoke():
    data = request.get_json(silent=True) or {}
    token = data.get('token')
    if not token:
        return err(400, 'token required')
    try:
        payload = jwt.decode(token, PUBLIC_KEY, algorithms=['RS256'], issuer=ISSUER, options={'require': ['exp', 'jti']})
    except jwt.ExpiredSignatureError:
        return err(401, 'token expired')
    except jwt.InvalidTokenError as e:
        return err(401, 'invalid token: %s' % e)
    remaining = int(payload['exp'] - time.time())
    try:
        redis_client.set('blacklist:%s' % payload['jti'], 'revoked', ex=max(remaining, 1))
    except redis.RedisError as e:
        log.error('redis write failed during revoke: %s', e)
        return err(503, 'blacklist unavailable')
    log.info('revoked jti %s', payload['jti'])
    return jsonify({'status': 'revoked', 'jti': payload['jti'], 'ttl': max(remaining, 1)}), 200

@app.route('/auth/validate', methods=['GET'])
def validate():
    auth = request.headers.get('Authorization', '')
    token = auth[7:] if auth.startswith('Bearer ') else request.args.get('token')
    payload, error = check_token(token)
    if error:
        return err(*error)
    return jsonify({'valid': True, 'sub': payload['sub'], 'jti': payload['jti'], 'type': payload.get('type'), 'exp': payload['exp'], 'iat': payload['iat'], 'iss': payload['iss']}), 200

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
